entries[208447] = { ["name"] = "Reinigendes Gewirr", ["text"] = "Questgegenstand\nBenutzen: Erschafft eine Kugel aus Wurzeln, die Ziele in einem läuternden Gewirr umschließen und ihr wahres Ich wiederherstellen kann. (4 Sek. Abklingzeit)\n\"Ein Gefühl der Ruhe befällt alle, die die Kugel berühren.\"" }
entries[208448] = { ["name"] = "Teewigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 30 sek. (Realzeit)\n\"Schmeckt, als hättet Ihr endlich alle Zeit der Welt. Wenn es nur länger anhalten würde.\"\nVerkaufspreis:" }
entries[208449] = { ["name"] = "Mellys Metronograf +++", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Synchronisiert desynchronisierte Wesen in der Nähe wieder mit dem Tempo unserer Zeitlinie. Jetzt mit experimentellen Modifikationen!\n\"Mellys patentierter Rhythmusmesser. Jetzt mit instabilen Modifikationen!\"" }
