entries[208460] = { ["name"] = "Der kaffeebefleckte Schädel von Dul'gan", ["text"] = "Questgegenstand\n\"Das einzige Überbleibsel von Dul'gan, einem begabten, vertrauenswürdigen Barista.\"" }
entries[208461] = { ["name"] = "Ein Buch von Medivh", ["text"] = "Questgegenstand\n\"Dieses Buch von Medivh enthält verbotene Aufzeichnungen über... die Festdekoration der Wächter?\"" }
entries[208462] = { ["name"] = "Phiole von Wachmach", ["text"] = "Questgegenstand\n\"Ein starker, orangener Energietrank. Soll gesünder sein als die violette Variante.\"" }
entries[208463] = { ["name"] = "Helm der Herrschlaft", ["text"] = "Questgegenstand\n\"Dieser stacheligen, metallenen Schlafmütze wird nachgesagt, mit ihrer Hilfe könne man Schlafende kontrollieren. Wenn man als Träger nur nicht ständig einschlafen würde...\"" }
entries[208464] = { ["name"] = "Der Feuersteineindämmungskrug", ["text"] = "Questgegenstand\n\"Einst enthielt er den Feuerstein, einen Gegenstand, der zu spontaner Selbstentzündung neigt. Wiederholt. Jetzt scheint der Krug leer zu sein.\"" }
entries[208465] = { ["name"] = "Die Glückwünsche von Elune", ["text"] = "Questgegenstand\n\"Ein Paar verzierter Kelche, welche diejenigen segnen sollen, die mit ihnen anstoßen.\"" }
entries[208466] = { ["name"] = "Himmelskarotte", ["text"] = "Questgegenstand\n\"Es heißt, sie würde die schnellsten Reittiere des Kosmos nähren. Aber warum hängt sie an einem Stock?\"" }
entries[208467] = { ["name"] = "Verpuppte Quintessenz", ["text"] = "Questgegenstand\n\"Dieser Behälter voll krabbelnder Käfer sollte über... etwas ausgeleert werden. Aber Ihr wollt nicht wirklich wissen, über was.\"" }
entries[208468] = { ["name"] = "Mechaschlüssel R1CH73R", ["text"] = "Questgegenstand\n\"Verleiht dem Fahrer Räder des Zorns. Vier davon, um genau zu sein.\"" }
