entries[208544] = { ["name"] = "Zorn von Frostherz", ["text"] = "Questgegenstand\nBenutzen: Ruft Vyranoths eisigen Zorn auf die Wildfeuergegner im Bereich herab, um sie zu betäuben und ihren erlittenen Schaden zu erhöhen. Entfernt Schattenflammenschilde. (10 Sek. Abklingzeit)\n\"Diese \"kleine\" Schuppe von Vyranoth ist so kalt, dass Ihr sie kaum anfassen könnt.\"" }
entries[208545] = { ["name"] = "Entzündetes Lagerfeuer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Entfacht vor Euch ein Lagerfeuer, auf dem für 5 Min. gekocht werden kann. (5 Min Abklingzeit)\n\"Keine Sorge, das ist ein kontrollierter Brand!\"" }
