entries[208549] = { ["name"] = "Büchsenfleisch", ["text"] = "Wird beim Aufheben gebunden\n\"Auf den ersten Blick wirkt es wertvoll... doch in Wirklichkeit findet Ihr hier keine inneren Werte.\"" }
entries[208550] = { ["name"] = "Drachen der Dracheninseln: Weiße Schuppen", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den Klippenwilddrachen, den erneuerten Protodrachen, den Hochlanddrachen, den windgeborenen Velocidrachen und den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[208551] = { ["name"] = "Duftender Sporenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Parfümiert Eure Rüstung mit einem leicht erdigen Aroma, um so zusätzliche optische Effekte für die Vorlagen der Ausrüstung des Höhlengräbers freizuschalten.\n\nDieser Effekt gilt für die ganze Kriegsmeute." }
