entries[208571] = { ["name"] = "Handzettel des Handwerkerkonsortiums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine besondere Notiz für eifrige Wettstreiter aller Ränge!\"" }
entries[208572] = { ["name"] = "Azurblauer Weltenkühler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört dieses Reittier oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In den entfernten Regionen Azeroths erzählt man sich Geschichten von einem furchtbaren Drachen, der das Land mit einem Leichentuch der Folter überzog. In manchen Versionen der Geschichte brachte seine feurige Gegenwart kataklysmischen Tod und Zerstörung in der ganzen Welt. In anderen Versionen ist er blau.\"\nBeute von:\nVerdammniswandler\nZone:\nTanaris" }
entries[208576] = { ["name"] = "Gedeihendes Wiederherstellungspartikel", ["text"] = "Questgegenstand\n\"Ein Partikel, der einen großen Teil des ausgefransten Traumlaubs wiederherstellen kann.\"" }
entries[208577] = { ["name"] = "Symbiotischer Leuchtsporengriff", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser anpassungsfähige Griff ist in der Lage, enormen Mengen fluktuierender Schattenflamme zu widerstehen. In Zusammenarbeit mit Lederverarbeitungsmeister Erden gefertigt.\"" }
entries[208578] = { ["name"] = "Konzentriertes weises Pergament", ["text"] = "Wird beim Aufheben gebunden\n\"Auf diesem Pergament werden Zauberformeln beschrieben, die Schattenflamme vom Träger fortleiten können. In Zusammenarbeit mit Meisterverzauberin Shalasar gefertigt.\"" }
entries[208581] = { ["name"] = "Leuchtende Ascheflocke", ["text"] = "Wird beim Aufheben gebunden\n\"Raue Asche, die sich an verschiedene Ausrüstungsgegenstände bindet. Kann nur durch Entzaubern entfernt werden.\"" }
entries[208587] = { ["name"] = "Keimendes Wiederherstellungspartikel", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Partikel, der einen kleinen Teil des ausgefransten Traumlaubs wiederherstellen kann.\"" }
entries[208588] = { ["name"] = "Quellendes Wiederherstellungspartikel", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Partikel, der einen gewissen Teil des ausgefransten Traumlaubs wiederherstellen kann.\"" }
entries[208592] = { ["name"] = "Rune der Schattenbindung", ["text"] = "Wird beim Aufheben gebunden\n\"Eine machtvolle Rune, die stärker wird, wenn man sie beschädigt. In Zusammenarbeit mit Inschriftenmeisterin Lydiara gefertigt.\"" }
entries[208593] = { ["name"] = "Schattentraumlaub", ["text"] = "Wird beim Aufheben gebunden\n\"Ein beeindruckend festes, ledriges Blatt. Kann im Smaragdgrünen Traum gefunden werden.\"" }
entries[208595] = { ["name"] = "Straffe Haltespule", ["text"] = "Wird beim Aufheben gebunden\n\"Eine gereizte Wurzel, die ihre Macht an die Elemente darum anpasst.\"" }
entries[208597] = { ["name"] = "Eadweards Notizen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert einen Stapel Notizen mit Informationen zu Schattenflamme, die Eadweard gesammelt hat. Gruppen- und Schlachtzugsmitglieder können die vom Historiker gesammelten und platzierten Notizen ebenfalls einsehen.\n\nDer Stapel Notizen wird 5 Min. lang verfügbar sein.\n\"Ein Stapel von Schriftstücken, die alles Wichtige zur Herstellung von Fyr'alath enthalten.\"" }
entries[208598] = { ["name"] = "Schreckensgefährt der Vornacht", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren magischen Besen oder gibt ihn wieder frei! Dieser Besen passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an. Während der Schlotternächte ist dies ein Spontanzauber.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das bevorzugte Transportmittel der Familie Fenlow (insbesondere während der Schlotternächte).\"\nHandelsposten" }
entries[208599] = { ["name"] = "Tiefgrüne Traumsaat", ["text"] = "Questgegenstand\n\"Ein leuchtender Samen aus der Pflanzenwelt des Traums. Er pulsiert schwach vor wilder Magie.\"" }
entries[208600] = { ["name"] = "Chromies zeitgesponnene Schulterpolster", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208606] = { ["name"] = "Somnagoras Herz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n70 ( 70)\n\"Ein mit Pflanzensaft bedecktes Mandragoraherz. Es riecht nach Pfirsichen und frischer Erde.\"" }
entries[208613] = { ["name"] = "Tuch des Hochgelehrten", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n1 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208614] = { ["name"] = "Weissagung der Urflamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 616.\nAnlegen: Eure Zauber und Fähigkeiten haben eine geringe Chance, Euch für 20 Sek. 'Vernichtende Flamme' zu gewähren, wodurch Eure kritischen Treffer zusätzlich 50% Feuerschaden verursachen, der auf Gegner in der Nähe aufgeteilt wird. Die Flamme kann insgesamt [ 97891 * (1 + Vielseitigkeit)] Schaden verursachen, bevor sie erlischt, was durch kritische Treffer weiter erhöht werden kann.\n\nSchaden und Maximalwert erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5 Gegnern.\n\"Eine Vision von endlosen Flammen.\"\nVerkaufspreis:" }
entries[208615] = { ["name"] = "Nymues entwirrende Spindel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+570 Intelligenz\nBenutzen: Kanalisieren, um die Essenz Eures Ziels aufzulösen, was im Verlauf von 3 Sek. 247877 Naturschaden verursacht und Euch 18 Sek. lang bis zu 2790 Meisterschaft gewährt.\n\nDer Schaden gegen bewegungsunfähige Ziele ist um 30% erhöht. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[208616] = { ["name"] = "Traumbinder, Webrahmen des großen Kreises", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n690 - 934 Schaden Geschwindigkeit 3.60\n(225.6 Schaden pro Sekunde)\n+2.666 Intelligenz\n+2.128 Ausdauer\nErhöht Eure Tempowertung um + 581.\nErhöht Eure Meisterschaftswertung um + 282.\nHaltbarkeit 120 / 120\nBenutzen: Webt nach 2 Sek. ein Traumgespinst unter Eurem Ziel, das 80339 Naturschaden verursacht, der auf alle Gegner innerhalb von 8 Metern aufgeteilt wird. Euer Ziel ist 4 Sek. lang bewegungsunfähig, während weitere Gegner um 80% verlangsamt werden. Dieser Effekt ist gegen gegnerische Spielercharaktere weniger effektiv.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu einem Maximum von 5 Gegnern. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[208617] = { ["name"] = "Belobigungsabzeichen der Schwarzen Klinge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht Euren Ruf bei den Rittern der Schwarzen Klinge um 260." }
entries[208619] = { ["name"] = "Die Tragödie von Erinethria", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Möge ihr Name und ihre Lektion auf alle Zeit in Erinnerung bleiben.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
