entries[208662] = { ["name"] = "Lichtgeschmiedeter Sucher", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n3 - 5 Schaden Geschwindigkeit 3.00\n(1.3 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\n\"Eine gewöhnliche Waffe der Armee des Lichts und ein Fluch für die restlichen Dämonen auf Argus.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208663] = { ["name"] = "Ashamanes Gewänder der Wiedergeburt", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen von Ashamanes Gewändern der Wiedergeburt.\n\"Diese Kleidung wird von den Druiden der Äschernen getragen und zollt dem gefallenen wilden Gott Ashamane Tribut.\"" }
entries[208664] = { ["name"] = "Ashamanes Segen der Wiedergeburt", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen von Ashamanes Segen der Wiedergeburt.\n\"Mit dem Zeichen der Druiden der Äschernen versehen.\"" }
entries[208665] = { ["name"] = "Eingewebtes Saronitexoskelett", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen des eingewebten Saronitexoskeletts.\n\"Die Netze der Neruber sind nicht nur zur Zierde da.\"" }
entries[208666] = { ["name"] = "Eingewebte Saronitwaffen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der eingewebten Saronitwaffen.\n\"Scharf genug, um durch Neruberseide zu schneiden.\"" }
entries[208667] = { ["name"] = "Flammen des Ungläubigen von Nathreza", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Flammen des Ungläubigen von Nathreza.\n\"Erfüllt die Herzen der Dämonen mit dem kontrollierten Chaos Eurer Flammen mit Schrecken.\"" }
entries[208668] = { ["name"] = "Gleven des Ungläubigen von Nathreza", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Gleven des Ungläubigen von Nathreza.\n\"Dieses aerodynamische Design wird Euch dabei helfen, jeden Dämon einzuholen.\"" }
entries[208669] = { ["name"] = "Gewand des besessenen Hüters", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen des Gewands des besessenen Hüters.\n\"Der Geist, der dieser Rüstung innewohnt, leistet gute Gesellschaft.\"" }
entries[208670] = { ["name"] = "Arachnophobie-Modus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Aktiviert den Arachnophobie-Modus." }
entries[208671] = { ["name"] = "Arsenal des besessenen Hüters", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen des Arsenals des besessenen Hüters.\n\"Der Weg der Hüter ist lautlos und tödlich.\"" }
entries[208672] = { ["name"] = "Juwelen des verlockenden Rufs", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Juwelen des verlockenden Rufs.\n\"Niemand kann der Versuchung widerstehen.\"" }
entries[208673] = { ["name"] = "Instrumente des verlockenden Rufs", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Instrumente des verlockenden Rufs.\n\"Der Weg der Hüter ist lautlos und tödlich.\"" }
entries[208674] = { ["name"] = "Trophäen des wilden Champions", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Trophäen des wilden Champions.\n\"Keine Bestie ist unserem Champion gewachsen.\"" }
entries[208675] = { ["name"] = "Aggressivität des wilden Champions", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Aggressivität des wilden Champions.\n\"So blass wie der Mond, so tödlich wie ein Reißzahn.\"" }
entries[208676] = { ["name"] = "Gesprossener Setzling", ["text"] = "Questgegenstand\n\"Ausgegrabener Samen eines violetten Vergissmeinnichts, der bereits zu sprießen beginnt.\"" }
entries[208677] = { ["name"] = "Kristallhammer von Eredath", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\nHaltbarkeit 50 / 50\n\"Eine gewöhnliche Waffe, die in der größten Stadt der Eredar von vielen geführt wird.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208680] = { ["name"] = "Windgeborener Velocidrache: Schlotternachtsrüstung", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den windgeborenen Velocidrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[208683] = { ["name"] = "Ritualkolben von Arinor", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\nHaltbarkeit 50 / 50\n\"Keine der Ritualisten unter den Arinorlandwarten haben überlebt, doch ihre Werkzeuge sind geblieben.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208684] = { ["name"] = "Kummer des Anachoreten", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Dolch\n2 - 5 Schaden Geschwindigkeit 3.60\n(1.0 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\n\"Ein Anachoret, der dazu gezwungen ist, sich auf seine Klinge zu verlassen, hat bereits mindestens einmal versagt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208685] = { ["name"] = "Geborgene Kaarinosklinge", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\nHaltbarkeit 50 / 50\n\"Es sind nur noch wenige Relikte der verlorenen Gipfel von Kaarinos vorhanden, doch denen, die sich noch an sie erinnern können, sind sie dafür umso bedeutender.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208686] = { ["name"] = "Velenitclaymore", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\n\"Einst von jenen Eredar geführt, die Velen ihre Treue geschworen haben, bevor die Dunkelheit über Argus kam.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208688] = { ["name"] = "Telaastispitzhacke", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Axt\n1 - 4 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\nHaltbarkeit 50 / 50\n\"Nur wenige erinnern sich an die reichen Minen der Weiten von Telaasti, die vor Jahrtausenden durch den Bau von Antorus verschlungen wurden.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208690] = { ["name"] = "Wurzelgeflechtschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n70 ( 70)\n\"Ein seltsames Wurzelgeflecht in Form eines Schlüssels. Was könnte er aufschließen?\"" }
entries[208691] = { ["name"] = "Argunitformation", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Geschenk von Arzaals Verbündeten, die noch auf Argus verweilen. Enthält Verschleierten Argunit und andere Materialien.\"\n<Zum Öffnen rechtsklicken>" }
entries[208692] = { ["name"] = "Uralter Wurzelgeflechtfoliant", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n70 ( 70)\n\"Das scheint ein uraltes Tagebuch eines Kräuterkundigen zu sein, einschließlich handgezeichneter Abbildungen zur Anatomie von Blumen. Vinna würde das gerne sehen.\"" }
