entries[208700] = { ["name"] = "Verzauberungen des Kampfmagisters", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Verzauberung des Kampfmagisters.\n\"Die Magister studierten viele Jahre lang, um Quel'Thalas zu schützen, also wurden Waffen hergestellt, die sie bei dieser Aufgabe unterstützen sollten.\"" }
entries[208702] = { ["name"] = "Gedächtnisessenz", ["text"] = "Questgegenstand\n\"Essenz einer der schwierigsten Erinnerungen von Gracus.\"" }
entries[208704] = { ["name"] = "Irdener Ruhestein des Tiefenbewohners", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Besteht aus Mineralien, die den tiefsten Tiefen entnommen wurden. Steine ähnlicher Natur sollen angeblich einen seltsamen Weg zum eigenen Ursprungspunkt öffnen.\"" }
entries[208705] = { ["name"] = "Druidentotem", ["text"] = "Questgegenstand\nBenutzen: Platziert das Totem, um Magie von geschwächten, flammenverderbten Wurzelpflegertreants und Wurzelpflegerwildwuchsen abzuziehen. (15 Sek. Abklingzeit)" }
