entries[208725] = { ["name"] = "Schuppen des Silberhorters", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Schuppen des Silberhorters.\n\"Geschmiedet von einem unbekannten Zeitenschmied in einer unbekannten Zeit.\"" }
entries[208726] = { ["name"] = "Schatz des Silberhorters", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen des Schatzes des Silberhorters.\n\"Die Zeitenschmiede reisten in die Zeit eines antiken Schmieds, um diese Waffen für einen zukünftigen Nutzen zu fertigen. Dieser Nutzen wird sich mit der Zeit offenbaren.\"" }
entries[208727] = { ["name"] = "Tarnung des Hornschreiterjägers", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Tarnung des Hornschreiterkriegers.\n\"Erfahrene Jäger tragen dieses zeremonielle Gewand während der Vorbereitung für eine Hornschreiterjagd, um die Jungjäger auf ihrer ersten Jagd zu inspirieren.\"" }
entries[208728] = { ["name"] = "Präferenz des Hornschreiterjägers", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Präferenz des Hornschreiterkriegers.\n\"Die Hornschreiter sind bekannt für ihre Tapferkeit und Wildheit und liefern eine gute Jagd und noch bessere Materialien für Waffen.\"" }
entries[208729] = { ["name"] = "Unheil des Vollstreckers von Krag'wa", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen des Unheils des Vollstreckers von Krag'wa.\n\"Hergestellt für Krag'was Hohepriester und die treuesten Anhänger des Loas.\"" }
entries[208730] = { ["name"] = "Werkzeuge des Vollstreckers von Krag'wa", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der Werkzeuge des Vollstreckers von Krag'wa.\n\"Krag'was Tempel wurden von treuen Zandalari bewacht, die für Ehre und Schutz bestimmte Waffen führten.\"" }
entries[208732] = { ["name"] = "Peitscherherz", ["text"] = "Questgegenstand\n80 ( 80)\n\"Der dichte Kern eines Peitschers. Er ist von einem rotgrünen Schleim mit starkem Geruch bedeckt.\"" }
entries[208733] = { ["name"] = "Drachenhornflöte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n\"Eine Flöte mit drei Löchern, die grob aus Drachenhorn geschnitzt wurde.\"" }
entries[208734] = { ["name"] = "Durchnässtes Hauptbuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n\"So durchnässt, dass die Tinte fast schon von den Seiten tropft.\"" }
entries[208735] = { ["name"] = "Eimer voller krankmachender Süßigkeiten", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nIn Schildhand geführt\n\"Bei manchen Süßigkeiten bekommt man ordentlich Saures zu spüren.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208736] = { ["name"] = "Hausaufgabe eines Astrologielehrlings", ["text"] = "\"Die hier dokumentierte Sternenkarte wirkt... merkwürdig.\"\nVerkaufspreis:" }
entries[208737] = { ["name"] = "Gelochter Bakarzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n\"Jemand hat vorsichtig ein Loch in diesen Bakarmilchzahn geschnitzt.\"" }
entries[208738] = { ["name"] = "Flüchtige Birne", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 Stunde (Realzeit)\nBenutzen: Nutzt den Saft einer Traumfrucht, um einen verletzten Träumerwaldgeist wiederzubeleben.\n\"Frisch gepresste Säfte haben magische Eigenschaften.\"" }
entries[208742] = { ["name"] = "Erneuerter Protodrache: Braufestrüstung", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den erneuerten Protodrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[208751] = { ["name"] = "Pusti", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[208752] = { ["name"] = "Horn des Cenarius", ["text"] = "Questgegenstand\nBenutzen: Blast das Horn des Cenarius, um alle Verbündeten in der Nähe zu ermächtigen. (2 Sek. Abklingzeit)" }
entries[208755] = { ["name"] = "Stab des uralten Seelenpriesters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\n\"Ein schmuckvolles Werkzeug für ein vergessenes, heiliges Ritual, das seit Jahrtausenden nicht mehr durchgeführt wurde.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
