entries[208763] = { ["name"] = "Schädelkappe des Direktors", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Die knochige Krempe hält das Licht von Euren Augen fern.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208769] = { ["name"] = "Foliant von Thomas Thomson", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein abgegriffener Foliant, dessen Einband der Name \"Thomson\" ziert.\"\n<Zum Lesen rechtsklicken>" }
entries[208770] = { ["name"] = "Blättergeisterstein", ["text"] = "Questgegenstand\n80 ( 80)\n\"Dieser Stein vibriert vor Lebensenergie. Ein schwaches Bild des Traums erscheint vor Eurem geistigen Auge, während eine dumpfe Stimme darum fleht, freigelassen zu werden.\"" }
entries[208775] = { ["name"] = "Aschphodill-Forschungsnotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Das leicht versengte Pergament ist voller Beobachtungsnotizen und Tintenflecken.\"" }
entries[208779] = { ["name"] = "Ungefüllter Eimer", ["text"] = "Questgegenstand\nBenutzen: Füllt den Eimer.\n\"Ein Eimer, der freundlicherweise von Professor Esche zur Verfügung gestellt wurde.\"" }
entries[208780] = { ["name"] = "Gefüllter Eimer", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Eimer gefüllt mit dem Wasser, das Amirdrassil umgibt.\"" }
entries[208781] = { ["name"] = "Symbiotischer Leuchtsporengriff", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Notizen zu den Eigenschaften von Zaralekleuchtsporen und ihren verschiedenen Einsatzmöglichkeiten. Geschrieben von Lederverarbeitungsmeister Erden.\"\nVerkaufspreis:" }
