entries[208821] = { ["name"] = "Aspektzeichen der Belobigung", ["text"] = "Saison 3 von Dragonflight\nWird beim Aufheben gebunden\nEinzigartig (12)\nVerkaufspreis:" }
entries[208822] = { ["name"] = "Ewiger Ruhestein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bringt Euch zurück an Eure letzte bekannte Position in den Schwellenden Zeitwegen.\n80 ( 80)" }
entries[208824] = { ["name"] = "Band des Kaldoreibeschützers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208825] = { ["name"] = "Renngürtel des jüngeren Zeithüters", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert in regelmäßigen Abständen Ringe für Gruppenmitglieder, durch die diese hindurchrasen können.\n\nDie Ringe können nicht zu nahe beieinander platziert werden. Die Abklingzeit ist während des Winterhauchfestes verringert. (30 Min Abklingzeit)\n\"Aus der Rennaccessoires-Kollektion 'Ich kann Andestrasz sein' gibt es jetzt ein neues Streckenbau-Set für den Heimbedarf!\"\nVerkaufspreis:" }
entries[208826] = { ["name"] = "Brief von Valunei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)" }
entries[208827] = { ["name"] = "Titanenschlüsselform", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine uralte Gussform mit dem Abdruck eines großen Schlüssels.\"" }
entries[208829] = { ["name"] = "Materialienliste für den Titanenschlüssel", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Eine Liste von Gegenständen, die für das Neuschmieden des Titanenschlüssels erforderlich sind.\"\n<Zum Lesen rechtsklicken>" }
entries[208830] = { ["name"] = "Neugeschmiedeter Titanenschlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Ein riesiger Schlüssel, der angeblich Schatzkammern der Titanen öffnen soll. Sind die Legenden wahr?\"" }
entries[208831] = { ["name"] = "Tyrs Titanenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhaltet die Vorlage der neuen Inkarnation von Tyrs Titanenschlüssel.\n\"Der Schlüssel pulsiert vor Magie. Tyrs Name ist in der Nähe des Schlüsselauges eingraviert.\"" }
entries[208832] = { ["name"] = "Tyrs Titanenschlüssel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stab\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208835] = { ["name"] = "Rotgoldstaub", ["text"] = "Wird beim Aufheben gebunden\n\"Diese staubigen roten Kügelchen sehen nicht wirklich nach Gold aus, aber der Götze hat sie dort gefunden, wo Koref erwartet hatte.\"" }
entries[208836] = { ["name"] = "Feuriger Flux", ["text"] = "Wird beim Aufheben gebunden\n\"Nicht ohne Handschuhe handhaben!\"" }
entries[208837] = { ["name"] = "Vermisste Frucht", ["text"] = "Wird beim Aufheben gebunden\nDauer: 10 min (Realzeit)\nBenutzen: Stellt im Verlauf von 20 Sek. ( 101250 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Ein Stück der gestohlenen Frucht.\"" }
entries[208839] = { ["name"] = "Rune der adaptiven Bindung", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Notizen zu der Wirkungsweise von tobenden und erweckten Elementen. Geschrieben von Inschriftenmeisterin Flüsterfeder.\"\nVerkaufspreis:" }
entries[208840] = { ["name"] = "Konzentriertes weises Pergament", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Notizen zur weisen Verzauberkunst und deren Fähigkeit, anderweitig instabile Magie zu konzentrieren. Geschrieben von Verzauberkunstmeisterin Glimmerstaub.\"\nVerkaufspreis:" }
entries[208841] = { ["name"] = "Klarsicht", ["text"] = "Questgegenstand\nBenutzen: Ermöglicht Euch das Aufspüren von aschegeladenen Wildtieren innerhalb von 40 Metern in den Verzweigten Wurzellanden. (5 Sek. Abklingzeit)" }
entries[208842] = { ["name"] = "Hüftgurt des Kaldoreibeschützers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nTaille Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208846] = { ["name"] = "Wiederhergestelltes Traumlaub", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ermächtigt einen Träger von Fyr'alath und erhöht die Zuwachsrate seines Schattentraumlaubs um 50%.\n\"Das Laub sieht robust und kräftig aus.\"" }
entries[208850] = { ["name"] = "Mini-Maggz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[208852] = { ["name"] = "Grabesbanner der Maruuk", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Das Banner ist mit einem uralten Text der Zentauren beschriftet. Vielleicht kann Sansok Khan in Maruukai Euch helfen, sie zu lesen.\"" }
entries[208856] = { ["name"] = "Fussel", ["text"] = "Verkaufspreis:" }
entries[208857] = { ["name"] = "Zeichnung zum Pfad von Ishtaar", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Jhara gab Euch eine Zeichnung der Statue von Ohn'ahra. Ihr solltet das Papier verwenden, um Notizen zum Pfad von Ishtaar aufzuschreiben.\"\n<Zum Lesen rechtsklicken>" }
entries[208858] = { ["name"] = "Hochlanddrache: Piratentagrüstung", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den Hochlanddrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
