entries[208879] = { ["name"] = "Ensemble: Zier des Kaldoreibeschützers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der Zier des Kaldoreibeschützers. Dieses Set kann nur von Charakteren der Nachtelfen getragen werden.\n\"Für jene Nachtelfen, die im Dienst für den Wald, den Mond und das Volk der Kaldorei große Leistungen vollbringen.\"" }
entries[208881] = { ["name"] = "Schauderschnappblüte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\n\"Eine andersweltliche Blume, die eine geisterhafte Kälte verströmt.\"" }
