entries[208883] = { ["name"] = "Sandkastensturmgreif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Hüpft auf diesen federnden Spielzeuggreifen oder hebt Eure Waffe und ruft den Donner herbei, um einen übermütigen Ritt zu erleben. (3 Min Abklingzeit)\n\"Warnung: Sicherheitsgeschirr nicht im Lieferumfang enthalten.\"" }
entries[208884] = { ["name"] = "Wurzelwiederherstellungsfrucht", ["text"] = "Questgegenstand\nBenutzen: Entzieht der traumgewachsenen Heilfrucht die Essenz und versucht, Gracus zu heilen.\n\"Eine aus dem Traum gewachsene Frucht, die von Heilungsmagie erfüllt ist und auf Wesen der Natur die größte Wirkung hat.\"" }
