entries[208886] = { ["name"] = "Feurige Essenz", ["text"] = "Questgegenstand\n\"Ein zähflüssiger Klumpen, der Hitze ausstrahlt. Wie ein schleimiges Lagerfeuer.\"" }
entries[208887] = { ["name"] = "Erdens Notizen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Hastig geschriebene Notizen zu verschiedenen Reagenzien, die für einen symbiotischen Leuchtsporengriff erforderlich sind.\"\nVerkaufspreis:" }
entries[208888] = { ["name"] = "Notiz eines Kontakts der Kirin Tor", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Bobby Carlisle gab Euch diese Notiz, um Euch dabei zu helfen, in Karazhan ein Buch zu finden, das Informationen zu den Tafeln und ihren Inhalten enthalten sollte.\"\n<Zum Lesen rechtsklicken>" }
