entries[208927] = { ["name"] = "Sandschimmerperle", ["text"] = "Questgegenstand\n\"Für ihre außergewöhnliche Schönheit berüchtigt.\"" }
entries[208928] = { ["name"] = "Zaqaliverzierungen", ["text"] = "Questgegenstand\n\"Dies scheint ein fast unbeschädigter Stein mit einer kleinen Verzierung zu sein.\"" }
entries[208929] = { ["name"] = "Tolle Sehenswürdigkeiten in Valdrakken", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Einige interessante Orte, die man aus völlig normalen Gründen besuchen sollte. - Klaudia Huhu\"\n<Zum Lesen rechtsklicken>" }
entries[208930] = { ["name"] = "Samtige Peitscherblätter", ["text"] = "Questgegenstand\n\"Weich und zart, perfekt für ein Schlaflager.\"" }
entries[208931] = { ["name"] = "Seidiger Salbei", ["text"] = "Questgegenstand\n\"Dick und weich, sehr gemütlich.\"" }
entries[208932] = { ["name"] = "Ein Teil des vierten Hinweises", ["text"] = "Geheimnisse von Azeroth\n\"Ein Teil eines Hinweises, um Mimirons erstes Stück zu finden.\"\n<Zum Lesen rechtsklicken>" }
