entries[208936] = { ["name"] = "Gesammelter Bericht", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Finalisierte Ergebnisse für Klaudia Huhu.\"" }
entries[208937] = { ["name"] = "Ein schlammiges Tagebuch", ["text"] = "\"Ihr habt dieses Tagebuch im Gras gefunden, und seine Seiten sind voller Matsch. Die letzten Seiten sind ein Fenster in eine gebrochene Seele.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[208938] = { ["name"] = "Metamorpher Ruß", ["text"] = "Questgegenstand\n\"Die beständige Glut in dieser Asche scheint ihre Form zu verändern, während Ihr sie beobachtet.\"" }
entries[208939] = { ["name"] = "Gorridar, Dunkelklinge des Zerreißers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n\"Bösartigkeit und Hass, verbunden zu einer Klinge, die ganze Welten verwüsten kann. Hütet Euch vor jenen, die eine solche Klinge neidvoll betrachten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208940] = { ["name"] = "Leerengesang, Stab des Herolds", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stab\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n\"Ein Geschenk von Dimensius, verliehen zur Blütezeit des Schwarzen Imperiums. Vom Schatten berührte werden von seinem quälenden Flüstern angezogen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208941] = { ["name"] = "M'thorus, Dolch des Großen Entwurfs", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Dolch\n1 Schaden Geschwindigkeit 1.80\n(0.6 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n\"Den Schatten darf nicht gestattet werden, zu schwären. Chaos muss niedergerungen werden, wo es sich einnistet. Wahre Kinder der Titanen werden dem Ruf ihrer Erschaffer folgen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208942] = { ["name"] = "Bewahrerbefehle Drei", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Ein Notizzettel, der ein Kugelartefakt beschreibt, das die Bewahrer gerettet wissen wollen.\"\n<Zum Lesen rechtsklicken>" }
entries[208943] = { ["name"] = "Arsenal: Kosmische Waffentruhe", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die in der kosmischen Waffentruhe des Arsenals enthaltenen Erscheinungen ein.\n\"Aus dem uralten Gewebe des Kosmos geschmiedete Waffen. Wer diese Sammlung zusammengestellt hat, bleibt ebenso rätselhaft wie die Gründe dafür. Wer sie führt, zieht die Augen jener auf sich, die solche Macht suchen.\"" }
entries[208944] = { ["name"] = "Kugel von Rathmus", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Titanenschrift ziert die Metallbänder, die die glühende Kugel umgeben.\"" }
entries[208945] = { ["name"] = "Parakausale Kiste", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Öffnet die Kiste, um 500 parakausale Flocken zu erhalten.\n\"Für das Wohlergehen der Zeitlinie wird leider empfohlen, die Kiste erst zu öffnen, nachdem sie versendet wurde.\"" }
entries[208946] = { ["name"] = "Brennende Rune", ["text"] = "Questgegenstand\n\"Eine mysteriöse Gravur, die unangenehme Hitze ausstrahlt.\"" }
entries[208947] = { ["name"] = "Verzauberte Gießkanne", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Spritzt Wasser auf verzauberte Sträucher und verleiht ihnen damit Energie, um sich Magnolia Eich zuzuwenden.\n\"Mächtiger als die durchschnittliche Gießkanne.\"" }
entries[208949] = { ["name"] = "Aufgeheizter Ruhestein", ["text"] = "Questgegenstand\n\"Warm und einladend, großartig zum Aufwärmen der Hände.\"" }
entries[208950] = { ["name"] = "Smaragdfaser", ["text"] = "Questgegenstand\n\"Eine robuste Faser, die erstaunlich zugfest ist.\"" }
entries[208951] = { ["name"] = "Parakausaler Verbund", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Zerschmettert dies, um 1000 parakausale Flocken zu erhalten.\n\"Eine Kristallformation, die sich kurz vor der Kollision zweier Zeitwege bildet und aus verdichteten Sanden der Zeit besteht.\"" }
entries[208952] = { ["name"] = "Soridormis Empfehlungsschreiben", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lest dies, um 1000 Ruf bei Soridormi zu erhalten.\n\"Ein Empfehlungsschreiben unterzeichnet von Soridormi.\"" }
entries[208955] = { ["name"] = "Gestohlener Traumsplitter", ["text"] = "Questgegenstand" }
entries[208956] = { ["name"] = "Intakte Primalistenkleidung", ["text"] = "Questgegenstand\n\"Es ist gut, dass das Blut auf der Kleidung optional war. Das hätte sonst sehr lange dauern können.\"" }
entries[208957] = { ["name"] = "Leitung des Südlichen Sturms", ["text"] = "Questgegenstand\n80 ( 80)\n\"Der uralte Obelisk scheint aus einem Stück elektrisch geladenem Glas oder Kristall gehauen zu sein.\"" }
entries[208958] = { ["name"] = "Notizen zum uralten Tyrholdartefakt", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Enthält Notizen von Kathos und Bobby zu den Sicherheitsvorkehrungen des Artefakts bei Tyrhold.\"\n<Zum Lesen rechtsklicken>" }
entries[208959] = { ["name"] = "Taesavir, Schwert des Großen Entwurfs", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n\"Eine Klinge, so scharf, dass sie nur von Aggramar selbst geschliffen werden kann. Jene, die sich dem Willen der Titanen widersetzen, sollten sich vor ihrem Träger hüten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208960] = { ["name"] = "Titanischer Fokussierkristall", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Dies ist eindeutig eins der Objekte, die zertrümmert wurden und für den zweiten Satz an Artefaktschlössern benötigt werden.\"" }
entries[208962] = { ["name"] = "Siederas, Breitschwert des Zerreißers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n\"Aus böswilligem Chaos geschmiedet, um das Herz des Ziels zu treffen. Jene, deren Seelen mit alles verzehrender Wut brennen, werden von seinem dunklen Feuer angezogen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[208965] = { ["name"] = "Titanenblockschlüssel", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Dies ist eindeutig eins der Objekte, die zertrümmert wurden und für den zweiten Satz an Artefaktschlössern benötigt werden.\"" }
