entries[208977] = { ["name"] = "Sehr wichtige Baumvorräte", ["text"] = "Questgegenstand\n\"Lady Mondbeere besteht darauf, dass es von höchster Wichtigkeit für das Errichten des Lagers ist, diese Vorratskisten zurückzuholen.\"" }
entries[208979] = { ["name"] = "10.2 Monster - Merithra - Robe", ["text"] = "Brust Stoff\n1 Rüstung\nVerkaufspreis:" }
entries[208980] = { ["name"] = "Kasten kosmischer Kuriositäten", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\n\"Die Oberfläche der Truhe ist in Sprachen graviert, die mit Ordnung, Teufelsmagie und der Leere in Verbindung stehen. Sie ist durch Magie versiegelt und weist keine einzige Naht und keinerlei Scharniere auf.\"" }
entries[208981] = { ["name"] = "10.2 Monster - Merithra - Wrist", ["text"] = "Handgelenk Stoff\n1 Rüstung\nVerkaufspreis:" }
