entries[208983] = { ["name"] = "Yvelyns Unterstützung", ["text"] = "Questgegenstand\nBenutzen: Ruft Yvelyn, um Euch in die Lüfte zu tragen und Gegner anzugreifen. (5 Sek. Abklingzeit)\n80 ( 80)" }
entries[208984] = { ["name"] = "Erstes Boosterteil", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nBenutzen: Kombiniert die erste, zweite und dritte Schubdüse in der Nähe einer ermächtigen arkanen Schmiede, um Mimirons Sprungdüsen zu schmieden und anzutreiben." }
entries[208985] = { ["name"] = "Bescheuerter Hut", ["text"] = "Questgegenstand\nBenutzen: Setzt einem schlafenden Druiden heimlich einen lustigen Hut auf.\n\"Ein lustiger Partyhut, den Lady Mondbeere in den Smaragdgrünen Traum gebracht hat, um ihn Druiden aufzusetzen.\"" }
