entries[209017] = { ["name"] = "Teleportalerschaffer", ["text"] = "Questgegenstand\nBenutzen: Erstellt ein experimentelles Teleportal, mit dem Ihr zu Orten innerhalb des Traums reisen könnt, die Forschungsleuchtfeuer enthalten. (15 Sek. Abklingzeit)\n\"Ingenieursportalerschaffer.\"" }
entries[209018] = { ["name"] = "Glühtropfenzucker", ["text"] = "Questgegenstand\n\"Weicher, luftiger Pollen, gesammelt von Schattenglühtropfen. Riechen außerordentlich süß, hauptsächlich nach Vanille mit Spuren von Zimt. Allerdings ist es extrem gefährlich, ihn zu essen.\"" }
entries[209019] = { ["name"] = "Beschworenes zuckerfreies Feuerwassersorbet", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Herbeigezauberter Nachtisch (1)\nBenutzen: Erhöht Eure Größe.\nVerkaufspreis:" }
entries[209021] = { ["name"] = "Abgeworfene Flugfedern", ["text"] = "Questgegenstand\n\"Lange, weiche Federn, die von einer großen Schlummereule abgeworfen wurden.\"" }
entries[209024] = { ["name"] = "Beutegefüllter Kürbis", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schlotternächte\n<Zum Öffnen rechtsklicken>" }
entries[209026] = { ["name"] = "Prall gefüllter Kürbis", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schlotternächte\n<Zum Öffnen rechtsklicken>" }
entries[209033] = { ["name"] = "Abgenutzte Teufelsstahlgebetsrute", ["text"] = "\"In die Rute sind die Worte \"Seine Macht ist unser Glaube. Sein Wort ist unsere Macht. Sein Wille ist die Wiedergeburt des Brennendes Kreuzzugs\" eingraviert.\"\nVerkaufspreis:" }
entries[209034] = { ["name"] = "Halb fertiggestellte Invasionspläne", ["text"] = "\"Unvollständige Pläne für eine neue Legionsinvasion einer entfernten Welt, von der Ihr noch nie gehört habt.\"\nVerkaufspreis:" }
entries[209035] = { ["name"] = "Ruhestein der Flamme", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Heimat ist dort, wo Eure Flamme am hellsten brennt.\"" }
entries[209036] = { ["name"] = "Truhe mit Schätzen aus Amirdrassil", ["text"] = "Wird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
entries[209037] = { ["name"] = "Truhe mit Schätzen aus Amirdrassil", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
entries[209038] = { ["name"] = "Tyrs Titanenschlüssel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[209039] = { ["name"] = "Tyrs Titanenschlüssel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[209040] = { ["name"] = "Tyrs Titanenschlüssel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[209044] = { ["name"] = "Orangenes Braufestbollwerk", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\nHaltbarkeit 30 / 30\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[209048] = { ["name"] = "Angesengter Handzettel", ["text"] = "Questgegenstand\n\"Pergament, dass stark nach Schwefel und Asche riecht, voller hingekritzelter Wörter und Kohleflecken.\"" }
entries[209049] = { ["name"] = "Essenz der endlosen Flamme", ["text"] = "Questgegenstand\n\"Der winzige Splitter sieht zerbrechlich und doch stets strahlend aus. Er ist nicht zu heiß, um ihn zu berühren, aber seine Wärme lässt nach.\"" }
entries[209050] = { ["name"] = "Somniumrinde", ["text"] = "Questgegenstand\nEinzigartig\n80 ( 80)\n\"Die Rinde des Somniumbaums kann als Heilmittel für viele Leiden verwendet werden.\"" }
entries[209051] = { ["name"] = "Schlafende Pracht", ["text"] = "Questgegenstand\nEinzigartig\n80 ( 80)\n\"Diese orange-gelben Blumen sollen erscheinen und blühen, nachdem ein Druide aus einem langen und erholsamen Schlaf erwacht ist. Sie ähneln der aufgehenden Sonne und werden als Metapher für den Sonnenaufgang oder einen Neubeginn verwendet.\"" }
entries[209052] = { ["name"] = "Gebräufass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschwört ein rollendes Fass und reitet es 30 Sek. lang. (10 Min Abklingzeit)" }
entries[209053] = { ["name"] = "Grünes Braufestbollwerk", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\n\"Riecht nach Braufest.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[209054] = { ["name"] = "Ritualarznei", ["text"] = "Questgegenstand\nEinzigartig\n80 ( 80)\n\"Dieses ritualistische Heilmittel soll das Band zwischen einer lebenden Kreatur und einem Traumgeist brechen können.\"" }
entries[209055] = { ["name"] = "Drittes Boosterteil", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nBenutzen: Kombiniert die erste, zweite und dritte Schubdüse in der Nähe einer ermächtigen arkanen Schmiede, um Mimirons Sprungdüsen zu schmieden und anzutreiben." }
entries[209060] = { ["name"] = "Tiefgrünes Panzerdon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die knorrigen Hörner dieser Panzerdon sind viel härter als Knochen.\"\nErfolg:\nSchlüsselsteinmeister von Dragonflight: Saison Drei\nKategorie:\nDungeons" }
entries[209061] = { ["name"] = "Ishtaar Rethons Grabesbanner", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Der Text auf dem Banner stellt die Pilgerschaft von Ishtaar Rethon dar. Jhara beim Nadelholzposten weiß, wo sie beginnt.\"" }
