entries[209344] = { ["name"] = "Inbrunstinsigne des tiefgrünen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 634.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 1346 zu erhöhen.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[209345] = { ["name"] = "Emblem des tiefgrünen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+603 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht 15 Sek. lang die maximale Gesundheit um 177846 . (2 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[209346] = { ["name"] = "Medaillon des tiefgrünen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+603 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[209347] = { ["name"] = "Siegel der Anpassung des tiefgrünen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+603 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[209348] = { ["name"] = "Lydiaras Notizen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Notizen zu der Wirkungsweise von tobenden und erweckten Elementen. Geschrieben von Inschriftenmeisterin Flüsterfeder.\"\nVerkaufspreis:" }
entries[209349] = { ["name"] = "Lydiaras Notizen zu Runenreagenzien", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teilt Lydiaras Notizen mit einem wohlgesinnten Inschriftenkundigen, um ihm vorübergehend beizubringen, wie Lydiaras Bindungsrune hergestellt werden kann. Der Inschriftenkundige muss sich in der gleichen Gruppe befinden. (30 Min Abklingzeit)\n\"Notizen zu den Anforderungen für die Herstellung einer experimentellen Rune der Schattenbindung. Geschrieben von Inschriftenmeisterin Flüsterfeder.\"" }
entries[209350] = { ["name"] = "Shalasars Notizen zu weiser Magie", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Notizen zu den Anforderungen für die Herstellung eines experimentellen konzentrierten weisen Pergaments. Geschrieben von Meisterverzauberin Glimmerstaub.\"\nVerkaufspreis:" }
