entries[209416] = { ["name"] = "Schildkröteneierschalen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\n\"Schalen von den Eiern der Schildkröten, die in der Gegend leben.\"\nVerkaufspreis:" }
entries[209417] = { ["name"] = "Ensemble: Gewand des donnernden Sturmreiters", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen des Gewands des donnernden Sturmreiters.\n\"Nur jene, die ihre Geschwindigkeit und Genauigkeit in den Greifenrennen unter Beweis stellen, erhalten die Ehre, dieses knisternde Ensemble zu tragen.\"" }
entries[209419] = { ["name"] = "Verkohlte Elementarüberreste", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Kombiniert 20 verkohlte Elementarüberreste, um etwas Neues zu erschaffen.\n\"Diese großen Fragmente wurden unter mächtigen Druiden der Flamme im Traumsprung gefunden. Sie scheinen voneinander angezogen zu werden.\"" }
entries[209428] = { ["name"] = "Wolfgeisterstein", ["text"] = "Questgegenstand\n80 ( 80)\n\"Dieser Stein hat scharfe Kanten, was Euch mit Selbstbewusstsein, Geduld und Konzentration erfüllt – allen Eigenschaften eines Spitzenjägers.\"" }
entries[209429] = { ["name"] = "Mondgeisterstein", ["text"] = "Questgegenstand\n80 ( 80)\n\"An diesem brüchigen Stein ist nichts Besonderes, bis Ihr ihn berührt und das enorme Gewicht der Vergangenheit über Euch hereinbrechen spürt.\"" }
entries[209430] = { ["name"] = "Bärengeisterstein", ["text"] = "Questgegenstand\n80 ( 80)\n\"Dieser Stein fühlt sich warm an. Ihr spürt die rohe Wut, die er verströmt. Der Geist darin könnte gefährlich sein.\"" }
entries[209431] = { ["name"] = "Pilzschaber", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\n\"Ein Gerät, speziell dafür hergestellt, Pilzschimmel von Gegenständen zu kratzen. Normalerweise bei dem Experten für Pilze, Finneas Fungulf, erhältlich.\"" }
