entries[209866] = { ["name"] = "Ritualmesser des Dornsprechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Führt ein Drustritual am Kadaver eines hilfsbereiten Wildtiers durch. (2 Sek. Abklingzeit)\n\"Ein geschärftes Messer mit einem Dornengriff. In den Schaft ist ein Hirsch geschnitzt.\"\nVerkaufspreis:" }
