entries[209870] = { ["name"] = "Sprungfänger", ["text"] = "Benutzen: Entlässt ein gefangenes Fragment des Traumsprungs in die Freiheit, um dessen Effekte an der Küste des Erwachens, auf den Ebenen von Ohn'ahra, im Azurblauen Gebirge und in Thaldraszus zu nutzen, unabhängig von der Position des Traumsprungs. (30 Min Abklingzeit)\n\"Ein winziges Partikel der Macht funkelt in den verknoteten Fäden.\"\nVerkaufspreis:" }
