entries[209875] = { ["name"] = "Blutige Rüstungsfetzen", ["text"] = "Questgegenstand\n\"Die Rüstungsfetzen aus zerschmettertem Holz und verdrehtem Metall sind mit dem Blut ihres ehemaligen Trägers besudelt.\"" }
